def get_ludic(n):
    result = []
    for num in range(1, n + 1):
        if all(num % i != 0 for i in range(2, int(num**0.5) + 1)):
            result.append(num)
    return result

# Test the function with the provided example
print(get_ludic(10)) # Expected output: [1, 2, 3, 5, 7]

