import re

def find_literals(text, pattern):
    match = re.search(pattern, text)
    if match:
        start_index = match.start()
        end_index = match.end()
        return (match.group(), start_index, end_index)
    else:
        return None

# Test the function
print(find_literals('The quick brown fox jumps over the lazy dog.', 'fox')) # Should return ('fox', 16, 19)
