def bell_number(n):
    if n <= 1:
        return 1
    else:
        return (bell_number(n-1) + bell_number(n-2)) * n / factorial(n) 

def factorial(n):
    f = 1
    for i in range(1, n+1):
        f *= i
    return f

def bell_number(n):
    return int(factorial(n)**0.5) - 1 + 1 // factorial(n)

